<script setup lang="ts">
import { computed, reactive, watch } from 'vue'
import type { CategoryOption, ExampleInput, PointInput, QuestionInput } from '../types/learning'

const props = defineProps<{ point: PointInput | null; categories: CategoryOption[]; saving?: boolean }>()
const emit = defineEmits<{ save: [PointInput]; cancel: [] }>()

const emptyQuestion = (): QuestionInput => ({ prompt: '', options: ['', ''], answer: '', explanation: '' })
const emptyExample = (): ExampleInput => ({ title: '', language: 'javascript', code: '', description: '', runnable: true })
const form = reactive<PointInput>({ categoryId: 0, title: '', summary: '', note: { keyPoints: '', body: '' }, questions: [], examples: [] })
const activeSection = reactive({ section: 'basics' })
const isEdit = computed(() => Boolean(props.point))

function replaceForm(point: PointInput | null) {
  const source = point || { categoryId: props.categories[0]?.id || 0, title: '', summary: '', note: { keyPoints: '', body: '' }, questions: [], examples: [] }
  form.categoryId = source.categoryId || props.categories[0]?.id || 0
  form.title = source.title || ''
  form.summary = source.summary || ''
  form.note = { keyPoints: source.note?.keyPoints || '', body: source.note?.body || '' }
  form.questions = (source.questions || []).map((question) => ({ prompt: question.prompt, options: [...question.options], answer: question.answer, explanation: question.explanation }))
  form.examples = (source.examples || []).map((example) => ({ title: example.title, language: example.language, code: example.code, description: example.description || '', runnable: example.runnable }))
}
watch(() => props.point, replaceForm, { immediate: true })

function addQuestion() { form.questions.push(emptyQuestion()); activeSection.section = 'questions' }
function addOption(question: QuestionInput) { if (question.options.length < 8) question.options.push('') }
function removeOption(question: QuestionInput, index: number) { if (question.options.length > 2) { if (question.answer === question.options[index]) question.answer = ''; question.options.splice(index, 1) } }
function removeQuestion(index: number) { form.questions.splice(index, 1) }
function addExample() { form.examples.push(emptyExample()); activeSection.section = 'examples' }
function removeExample(index: number) { form.examples.splice(index, 1) }
function submit() { emit('save', { categoryId: form.categoryId, title: form.title.trim(), summary: form.summary.trim(), note: { ...form.note }, questions: form.questions.map((question) => ({ ...question, options: [...question.options] })), examples: form.examples.map((example) => ({ ...example })) }) }
</script>

<template>
  <div class="editor-backdrop" @click.self="emit('cancel')">
    <section class="editor-modal" aria-labelledby="editor-title">
      <header class="editor-header"><div><span class="section-kicker">KNOWLEDGE POINT EDITOR</span><h2 id="editor-title">{{ isEdit ? '编辑知识点' : '创建知识点' }}</h2></div><button class="modal-close" type="button" aria-label="关闭编辑器" @click="emit('cancel')">×</button></header>
      <div class="editor-scroll">
        <div class="editor-section"><button class="editor-section-title" type="button" @click="activeSection.section = 'basics'">01 <strong>基础信息</strong><span>BASE INFORMATION</span></button><div v-show="activeSection.section === 'basics'" class="editor-fields"><label class="form-label">所属分类<select v-model.number="form.categoryId"><option v-for="category in categories" :key="category.id" :value="category.id">{{ category.label }}</option></select></label><label class="form-label">知识点标题<input v-model="form.title" maxlength="200" placeholder="例如：事件循环与任务队列" /></label><label class="form-label">一句话摘要<textarea v-model="form.summary" maxlength="5000" placeholder="用一句话描述这个知识点..."></textarea></label></div></div>
        <div class="editor-section"><button class="editor-section-title" type="button" @click="activeSection.section = 'notes'">02 <strong>笔记内容</strong><span>LEARNING NOTES</span></button><div v-show="activeSection.section === 'notes'" class="editor-fields"><label class="form-label">核心要点<textarea v-model="form.note.keyPoints" class="editor-large-text" maxlength="60000" placeholder="概念、原则、易错点和记忆线索..." /></label><label class="form-label">我的笔记<textarea v-model="form.note.body" class="editor-large-text" maxlength="60000" placeholder="记录你的理解、例子和实践过程..." /></label></div></div>
        <div class="editor-section"><button class="editor-section-title" type="button" @click="activeSection.section = 'questions'">03 <strong>验证题目</strong><span>CHECK YOURSELF</span></button><div v-show="activeSection.section === 'questions'" class="editor-fields"><div v-if="!form.questions.length" class="editor-empty">还没有题目，先添加一道单选题。</div><article v-for="(question, questionIndex) in form.questions" :key="questionIndex" class="question-editor"><div class="question-editor-heading"><strong>题目 {{ String(questionIndex + 1).padStart(2, '0') }}</strong><button type="button" @click="removeQuestion(questionIndex)">删除</button></div><label class="form-label">题干<textarea v-model="question.prompt" maxlength="5000" placeholder="输入问题..."></textarea></label><div class="option-editor-heading"><span>选项</span><button type="button" @click="addOption(question)">＋ 添加选项</button></div><div v-for="(_, optionIndex) in question.options" :key="optionIndex" class="option-editor-row"><input v-model="question.options[optionIndex]" maxlength="1000" :placeholder="`选项 ${optionIndex + 1}`" /><button type="button" :disabled="question.options.length <= 2" @click="removeOption(question, optionIndex)">×</button></div><label class="form-label">正确答案<select v-model="question.answer"><option value="" disabled>选择正确选项</option><option v-for="option in question.options.filter(Boolean)" :key="option" :value="option">{{ option }}</option></select></label><label class="form-label">答案解析<textarea v-model="question.explanation" maxlength="5000" placeholder="告诉未来的自己为什么..." /></label></article><button class="editor-add-button" type="button" @click="addQuestion">＋ 添加一道题目</button></div></div>
        <div class="editor-section"><button class="editor-section-title" type="button" @click="activeSection.section = 'examples'">04 <strong>代码示例</strong><span>LEARN BY DOING</span></button><div v-show="activeSection.section === 'examples'" class="editor-fields"><div v-if="!form.examples.length" class="editor-empty">还没有代码示例，添加一个可以运行的片段。</div><article v-for="(example, exampleIndex) in form.examples" :key="exampleIndex" class="example-editor"><div class="question-editor-heading"><strong>示例 {{ String(exampleIndex + 1).padStart(2, '0') }}</strong><button type="button" @click="removeExample(exampleIndex)">删除</button></div><label class="form-label">标题<input v-model="example.title" maxlength="200" placeholder="例如：用闭包创建计数器" /></label><div class="editor-inline-fields"><label class="form-label">语言<select v-model="example.language"><option v-for="language in ['javascript', 'html', 'css', 'vue', 'typescript', 'text']" :key="language" :value="language">{{ language }}</option></select></label><label class="checkbox-label"><input v-model="example.runnable" type="checkbox" :disabled="!['javascript', 'html', 'css', 'vue'].includes(example.language)" /> 可以在浏览器运行</label></div><label class="form-label">说明<textarea v-model="example.description" maxlength="5000" placeholder="说明这个示例要验证什么..." /></label><label class="form-label">代码<textarea v-model="example.code" class="code-editor" maxlength="60000" spellcheck="false" placeholder="输入代码..." /></label></article><button class="editor-add-button" type="button" @click="addExample">＋ 添加代码示例</button></div></div>
      </div>
      <footer class="editor-footer"><button class="outline-button" type="button" @click="emit('cancel')">取消</button><button class="primary-button" type="button" :disabled="saving || !form.title.trim() || !form.categoryId" @click="submit">{{ saving ? '保存中...' : isEdit ? '保存修改' : '创建知识点' }} ↗</button></footer>
    </section>
  </div>
</template>

<style scoped>
.editor-backdrop { position: fixed; inset: 0; z-index: 30; display: grid; place-items: center; padding: 20px; background: rgba(22, 53, 48, .28); backdrop-filter: blur(5px); }.editor-modal { width: min(720px, 100%); max-height: min(860px, 94vh); display: flex; flex-direction: column; overflow: hidden; border: 1px solid #dce9df; border-radius: 15px; background: #fff; box-shadow: 0 30px 90px rgba(20, 64, 48, .2); }.editor-header, .editor-footer { flex-shrink: 0; display: flex; align-items: center; justify-content: space-between; padding: 24px 28px; }.editor-header { border-bottom: 1px solid #e7efe9; }.editor-header h2 { margin: 7px 0 0; color: #214940; font: 600 24px 'Space Grotesk'; }.editor-scroll { overflow: auto; padding: 0 28px; }.editor-section { border-bottom: 1px solid #e9f0eb; }.editor-section-title { width: 100%; display: flex; align-items: center; gap: 11px; padding: 17px 0; color: #8ba196; background: transparent; text-align: left; font: 10px 'DM Mono'; }.editor-section-title strong { color: #4e7462; font: 600 13px 'Space Grotesk'; }.editor-section-title span { margin-left: auto; font-size: 9px; }.editor-fields { padding: 0 0 22px; }.editor-large-text { min-height: 100px !important; }.editor-empty { padding: 15px; color: #9cacA4; border: 1px dashed #dce9df; border-radius: 7px; font-size: 11px; }.question-editor, .example-editor { margin-top: 13px; padding: 15px; border: 1px solid #e1ebe4; border-radius: 9px; }.question-editor-heading, .option-editor-heading { display: flex; align-items: center; justify-content: space-between; color: #668879; font-size: 11px; }.question-editor-heading button, .option-editor-heading button { padding: 3px 6px; color: #bf7b70; background: #fff5f2; border-radius: 4px; font-size: 10px; }.option-editor-heading { margin-top: 15px; color: #8aa197; }.option-editor-heading button { color: #629276; background: #edf6ef; }.option-editor-row { display: flex; gap: 6px; margin-top: 7px; }.option-editor-row input { flex: 1; min-width: 0; padding: 9px; border: 1px solid #e0eae3; border-radius: 5px; outline: none; color: #567466; font-size: 11px; }.option-editor-row button { width: 28px; color: #a7b5ae; background: transparent; font-size: 18px; }.editor-add-button { width: 100%; margin-top: 13px; padding: 10px; border: 1px dashed #bddac5; border-radius: 6px; color: #65947a; background: #f6fbf6; font-size: 11px; }.editor-inline-fields { display: flex; align-items: center; gap: 20px; }.editor-inline-fields .form-label { flex: 1; }.checkbox-label { display: flex; align-items: center; gap: 6px; color: #71897e; font-size: 11px; white-space: nowrap; }.checkbox-label input { accent-color: #589171; }.code-editor { min-height: 180px !important; color: #d1ebdb !important; background: #193a37 !important; font: 12px/1.7 Consolas, monospace !important; }.editor-footer { justify-content: flex-end; gap: 9px; border-top: 1px solid #e7efe9; }
@media (max-width: 600px) { .editor-header, .editor-footer, .editor-scroll { padding-left: 17px; padding-right: 17px; }.editor-inline-fields { align-items: flex-start; flex-direction: column; gap: 0; }.checkbox-label { margin-top: 0; } }
</style>
